"use client";

import { Button } from "../atoms/button";
import { cn } from "../lib/cn";
import { MOTION_DEFAULTS, type ToastMotion } from "../lib/motion";
import { exitDurationForMotion } from "../lib/presence";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";

export type ToastVariant = "default" | "success" | "warning" | "danger";
export type { ToastMotion };

export type ToastInput = {
  title: string;
  description?: string;
  variant?: ToastVariant;
  /** Auto dismiss ms. Default 4200. Set 0 to keep until closed. */
  duration?: number;
  /** Enter motion override for this toast */
  motion?: ToastMotion;
};

type ToastItem = ToastInput & {
  id: string;
  leaving?: boolean;
  motion?: ToastMotion;
};

type ToastContextValue = {
  toast: (input: ToastInput) => string;
  dismiss: (id: string) => void;
};

const ToastContext = createContext<ToastContextValue | null>(null);

const variantClass: Record<ToastVariant, string> = {
  default: "",
  success: "sg-toast-success",
  warning: "sg-toast-warning",
  danger: "sg-toast-danger",
};

export type ToastProviderProps = {
  children: ReactNode;
  position?: "top-right" | "bottom-right" | "bottom-center";
  /** Default enter motion for toasts */
  motion?: ToastMotion;
};

/**
 * Molecule system — Toast
 * Glass notifications via `useToast().toast({ title, description, variant })`.
 * Stack reflows with gap; leave uses presence-style delay matched to CSS exit.
 */
export function ToastProvider({
  children,
  position = "bottom-right",
  motion = MOTION_DEFAULTS.toast,
}: ToastProviderProps) {
  const [items, setItems] = useState<ToastItem[]>([]);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const dismiss = useCallback(
    (id: string) => {
      let leaveMs = exitDurationForMotion(motion);

      setItems((current) => {
        const target = current.find((item) => item.id === id);
        if (!target || target.leaving) {
          leaveMs = -1;
          return current;
        }
        leaveMs = exitDurationForMotion(target.motion ?? motion);
        return current.map((item) =>
          item.id === id ? { ...item, leaving: true } : item,
        );
      });

      if (leaveMs < 0) return;

      window.setTimeout(() => {
        setItems((current) => current.filter((item) => item.id !== id));
      }, leaveMs);
    },
    [motion],
  );

  const toast = useCallback(
    (input: ToastInput) => {
      const id =
        typeof crypto !== "undefined" && "randomUUID" in crypto
          ? crypto.randomUUID()
          : `toast-${Date.now()}-${Math.random().toString(16).slice(2)}`;

      const duration = input.duration ?? 4200;
      setItems((current) => [
        ...current,
        {
          id,
          title: input.title,
          description: input.description,
          variant: input.variant ?? "default",
          duration,
          motion: input.motion ?? motion,
        },
      ]);

      if (duration > 0) {
        window.setTimeout(() => dismiss(id), duration);
      }

      return id;
    },
    [dismiss, motion],
  );

  const value = useMemo(() => ({ toast, dismiss }), [toast, dismiss]);

  const positionClass =
    position === "top-right"
      ? "sg-toast-viewport-top-right"
      : position === "bottom-center"
        ? "sg-toast-viewport-bottom-center"
        : "sg-toast-viewport-bottom-right";

  const viewport =
    mounted &&
    createPortal(
      <ol
        className={cn("sg-toast-viewport", positionClass)}
        data-position={position}
        aria-live="polite"
        aria-relevant="additions text"
        aria-atomic="false"
      >
        {items.map((item, index) => (
          <li
            key={item.id}
            className={cn(
              "sg-toast",
              "sg-surface-frost-toast",
              variantClass[item.variant ?? "default"],
            )}
            data-leaving={item.leaving || undefined}
            data-motion={item.motion ?? motion}
            data-stack-index={index}
            style={
              {
                ["--sg-toast-i" as string]: String(index),
              } as CSSProperties
            }
          >
            <div>
              <p className="sg-toast-title">{item.title}</p>
              {item.description ? (
                <p className="sg-toast-description">{item.description}</p>
              ) : null}
            </div>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              iconOnly
              className="sg-toast-close"
              aria-label="Dismiss notification"
              disabled={item.leaving}
              onClick={() => dismiss(item.id)}
            >
              ×
            </Button>
          </li>
        ))}
      </ol>,
      document.body,
    );

  return (
    <ToastContext.Provider value={value}>
      {children}
      {viewport}
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) {
    throw new Error("useToast must be used within <ToastProvider>");
  }
  return ctx;
}

/** Values allowed in `cn(...)` — only strings survive. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ClassValue = string | false | null | undefined | 0 | 0n | boolean;

/**
 * Tiny class merger — no runtime deps.
 * Prefer this over pulling tailwind-merge until we need conflict resolution.
 */
export function cn(...parts: ClassValue[]): string {
  return parts.filter((part): part is string => typeof part === "string" && part.length > 0).join(" ");
}

/** Shared visual “look” languages across controls. */

export type ButtonLook = "solid" | "soft" | "glass" | "gradient" | "neon";

export type RadioLook = "dot" | "card" | "chip";

export type CheckboxLook = "box" | "card" | "pill";

export type SwitchLook = "track" | "ios" | "minimal";

export type BadgeLook = "soft" | "solid" | "outline" | "glow";

export type FieldLook = "solid" | "underline" | "filled" | "ghost";

export type SelectLook = "solid" | "soft" | "glass" | "gradient";

export type TabsLook = "pill" | "underline" | "segmented";

export type AvatarLook = "circle" | "rounded" | "soft";

export type TooltipLook = "frost" | "solid" | "accent";

export type CardLook = "flat" | "raised" | "outline" | "glow";

/**
 * Motion recipes — component-specific animation menus.
 * Parallel to `look` (visual surface). Always pair with `prefers-reduced-motion`.
 *
 * Defaults match the pre-motion global micro-interactions so existing UIs
 * keep the same feel when no prop is passed.
 */

/** Shared “off” token used on every control. */
export type MotionNone = "none";

export type ButtonMotion = MotionNone | "lift" | "press" | "sheen" | "ripple";

export type CheckboxMotion = MotionNone | "pop" | "draw" | "fade-in" | "bounce";

export type RadioMotion = MotionNone | "pop" | "dot-scale" | "ring-expand";

export type SwitchMotion = MotionNone | "snap" | "spring" | "elastic";

export type FieldMotion = MotionNone | "ring" | "underline-grow" | "glow";

export type SelectMotion = MotionNone | "fade" | "scale" | "slide-down";

export type TooltipMotion = MotionNone | "fade" | "scale" | "slide";

export type BadgeMotion = MotionNone | "pulse" | "pop-in" | "shimmer";

export type AvatarMotion = MotionNone | "lift" | "ring-pulse" | "status-ping";

/**
 * Tabs indicator + content enter.
 * - none: instant active swap
 * - fade: soft cross-fade on active chrome / content
 * - slide: moving pill or underline indicator (content still fades)
 */
export type TabsMotion = MotionNone | "fade" | "slide";

export type ModalMotion = MotionNone | "scale" | "fade" | "slide-up";

export type ToastMotion = MotionNone | "slide-in" | "pop";

export type CardMotion = MotionNone | "lift" | "glow-pulse";

/** Popover / DropdownMenu panel enter (same recipe set as Select menu). */
export type PopoverMotion = MotionNone | "fade" | "scale" | "slide-down";

export type DropdownMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Defaults — preserve current product feel. */
export const MOTION_DEFAULTS = {
  button: "lift",
  checkbox: "pop",
  radio: "pop",
  switch: "spring",
  field: "ring",
  select: "scale",
  tooltip: "scale",
  badge: "none",
  avatar: "lift",
  tabs: "slide",
  modal: "scale",
  toast: "slide-in",
  card: "lift",
  popover: "scale",
  dropdownMenu: "scale",
} as const satisfies Record<string, string>;

"use client";

import { useEffect, useState } from "react";

/**
 * Unmount delay so CSS exit animations can finish.
 * Keep in sync with token exit durations (~`--sg-duration-normal` / motion-med).
 */
export const EXIT_DURATION_MS = 200;

export type PresenceOptions = {
  /** 0 = unmount immediately (motion="none" or reduced-motion). */
  durationMs?: number;
};

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/** Map motion recipe → exit hold time. */
export function exitDurationForMotion(motion: string | undefined): number {
  if (motion === "none") return 0;
  if (prefersReducedMotion()) return 0;
  return EXIT_DURATION_MS;
}

/**
 * Keep a node mounted while `open` is true **and** briefly after it becomes false
 * so exit keyframes can play. Mirrors Radix presence / `data-state` pattern.
 */
export function usePresence(open: boolean, options?: PresenceOptions) {
  const durationMs = options?.durationMs ?? EXIT_DURATION_MS;
  const [mounted, setMounted] = useState(open);
  const [exiting, setExiting] = useState(false);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setExiting(false);
      return;
    }

    if (!mounted) return;

    if (durationMs <= 0) {
      setMounted(false);
      setExiting(false);
      return;
    }

    setExiting(true);
    const id = window.setTimeout(() => {
      setMounted(false);
      setExiting(false);
    }, durationMs);

    return () => window.clearTimeout(id);
  }, [open, durationMs, mounted]);

  return {
    /** Still in the DOM (open or playing exit). */
    mounted,
    /** Exit animation should run. */
    exiting,
    /** For `data-state`: open while interactive, closed while exiting. */
    state: (open && !exiting ? "open" : "closed") as "open" | "closed",
  };
}
